"""Pip writes the outcome of every step that has none (D-1036, founder 24 Nov 2026: a step's
"Outcome of this step" is generated by Pip, never left for the owner to type).

Pip writes outcomes when it writes a whole script; a script written before outcomes existed,
edited by hand, or given a new step has steps with none. Each save of a campaign's or an
inbound line's script that leaves such a step queues one pass on that holder
(`queue_after_save`), and the hourly sweep (`workers/step_outcomes.sweep_step_outcomes`)
queues the holders no save has reached, which is how scripts saved before this existed get
theirs. The pass (`workers/step_outcomes.write_step_outcomes`) writes only the missing ones and
never touches an outcome that is there.

The queue is the shared agent pass (`agents/agent_pass`), so a pass asked for while one waits
or runs is coalesced and a change made mid-pass is never lost. A burst of saves is one pass:
each save while a pass waits pushes its start back (`DEBOUNCE_S`), and the worker defers
itself until the burst is over.
"""

from __future__ import annotations

from typing import Final, Literal
from uuid import UUID

from calevate_shared.call_script import CallScript, stage_steps
from sqlalchemy import text
from sqlalchemy.ext.asyncio import AsyncSession

from apps.api.agents import agent_pass
from apps.api.agents.agent_pass import dead_sql
from apps.api.copilot.consent import account_content_may_reach_models

#: The ARQ name of the pass (`workers/step_outcomes`).
JOB: Final = "write_step_outcomes"
#: A pass starts this long after the last save that asked for it, so an owner saving the flow
#: several times in a row gets one pass over the script they ended with.
DEBOUNCE_S: Final = 30

HolderKind = Literal["campaign", "line"]

SLOTS: Final[dict[HolderKind, agent_pass.PassSlot]] = {
    "campaign": agent_pass.PassSlot(
        "step_outcomes", JOB, table="campaigns", gone="archived_at", id_key="campaign_id"
    ),
    "line": agent_pass.PassSlot(
        "step_outcomes", JOB, table="inbound_lines", gone="archived_at", id_key="line_id"
    ),
}


def table_of(kind: HolderKind) -> str:
    """The holder's table, as a conditional of literals so `scripts/check_raw_sql.py` can
    read it."""
    return "campaigns" if kind == "campaign" else "inbound_lines"


def missing_steps(script: CallScript | None) -> list[int]:
    """The steps of a structured script that have no outcome, in order. A raw script and one
    without stages have no steps to give one."""
    if script is None or script.raw_override is not None or not script.stages:
        return []
    have = {o.step for o in script.step_outcomes if o.outcome.strip()}
    return sorted(set(stage_steps(script.stages)) - have)


async def queue_after_save(
    session: AsyncSession, kind: HolderKind, holder_id: UUID, script: CallScript | None
) -> bool:
    """In the saving transaction: ask for a pass when `script` leaves a step without an
    outcome. True when a job was promised.

    A pass already waiting is pushed back instead (`DEBOUNCE_S`). Nobody pressed a button for
    this pass, so an account whose owner has not turned Pip on is marked `skipped` and left
    for the sweep to pick up once they do (`account_content_may_reach_models`)."""
    if not missing_steps(script):
        return False
    table = table_of(kind)
    tenant_id = (
        await session.execute(
            text(f"SELECT tenant_id FROM {table} WHERE id = :hid"), {"hid": holder_id}
        )
    ).scalar()
    if tenant_id is None:
        return False
    tenant = UUID(str(tenant_id))
    if not await account_content_may_reach_models(session, tenant_id=tenant):
        await session.execute(
            text(
                f"UPDATE {table} SET step_outcomes_state = 'skipped', step_outcomes_at = now() "
                "WHERE id = :hid AND step_outcomes_state IS DISTINCT FROM 'running'"
            ),
            {"hid": holder_id},
        )
        return False
    if await agent_pass.queue(session, SLOTS[kind], tenant_id=tenant, row_id=holder_id):
        return True
    await session.execute(
        text(
            f"UPDATE {table} SET step_outcomes_at = now() "
            "WHERE id = :hid AND step_outcomes_state = 'queued'"
        ),
        {"hid": holder_id},
    )
    return False


async def pending(session: AsyncSession, kind: HolderKind, holder_id: UUID) -> bool:
    """Is a pass waiting or running for this holder, with a live job behind it?"""
    return bool(
        (
            await session.execute(
                text(
                    f"SELECT step_outcomes_state IN ('queued', 'running') "
                    f"AND NOT {dead_sql(SLOTS[kind])} FROM {table_of(kind)} WHERE id = :hid"
                ),
                {"hid": holder_id},
            )
        ).scalar()
    )


__all__ = [
    "DEBOUNCE_S",
    "JOB",
    "SLOTS",
    "HolderKind",
    "missing_steps",
    "pending",
    "queue_after_save",
    "table_of",
]
